const a=brojac(); const b=brojac();
console.log(a(),a(),b());","pitanje":"Šta će se ispisati?","opcije":[{"key":"A","text":"1 2 1","why":"Tačan zaključak. Svaki poziv brojac pravi novo leksičko okruženje sa sopstvenim n. Funkcija a dva puta menja svoje n, dok b koristi odvojeno okruženje. Closure ne pamti samo kopiju početne vrednosti; zatvara pristup promenljivoj svog konkretnog poziva.","ok":true},{"key":"B","text":"1 1 1","why":"Ne važi tvrdnja „1 1 1”. Svaki poziv brojac pravi novo leksičko okruženje sa sopstvenim n.","ok":false},{"key":"C","text":"1 2 3","why":"Ne važi tvrdnja „1 2 3”. Svaki poziv brojac pravi novo leksičko okruženje sa sopstvenim n.","ok":false}],"tacanOdgovor":"1 2 1","objasnjenje":"Svaki poziv brojac pravi novo leksičko okruženje sa sopstvenim n. Funkcija a dva puta menja svoje n, dok b koristi odvojeno okruženje. Closure ne pamti samo kopiju početne vrednosti; zatvara pristup promenljivoj svog konkretnog poziva.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"1 2 1","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"03-r03","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"izolovano","okruzenje":"javascript-izolovano","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Metoda bez primaoca","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":""use strict";
const soba={temperatura:24, procitaj(){return this.temperatura;}};
const f=soba.procitaj;
console.log(f());","pitanje":"Zašto nastaje TypeError i kako dobiti 24?","opcije":[{"key":"A","text":"Promeniti const u let","why":"Ne važi tvrdnja „Promeniti const u let”. U strict režimu samostalan poziv obične funkcije ima this=undefined.","ok":false},{"key":"B","text":"Izbrisati use strict da bi metoda sigurno radila","why":"Ne važi tvrdnja „Izbrisati use strict da bi metoda sigurno radila”. U strict režimu samostalan poziv obične funkcije ima this=undefined.","ok":false},{"key":"C","text":"Izdvojena metoda nema primaoca; vezati je uz soba.","why":"Tačan zaključak. U strict režimu samostalan poziv obične funkcije ima this=undefined. Kada funkcija pokuša this.temperatura, dolazi do TypeError. Poziv soba.procitaj() ili bind(soba) eksplicitno obezbeđuje primaoca. Izbacivanje strict režima nije pouzdana popravka.","ok":true}],"tacanOdgovor":"Izdvojena metoda nema primaoca; vezati je uz soba.","objasnjenje":"U strict režimu samostalan poziv obične funkcije ima this=undefined. Kada funkcija pokuša this.temperatura, dolazi do TypeError. Poziv soba.procitaj() ili bind(soba) eksplicitno obezbeđuje primaoca. Izbacivanje strict režima nije pouzdana popravka.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"Izdvojena metoda nema primaoca; vezati je uz soba.","predlogPopravke":"const f = soba.procitaj.bind(soba); console.log(f()); // 24","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema","provera-popravke":"potrebna"}]}

