fajl.isecak:
function prosek(visine) {
  const zbir = visine.reduce((s, v) => s + v, 0);
  return visine.length ? zbir / visine.length : 0;
}

pojam.zapis:
const a = { temperatura: 24 };
const b = a;
b.temperatura = 25;

nedelja.dopunska-polja:
{"predavanjeMinuta":55,"diskusijaMinuta":35,"samostalniZadaci":"van-casa","preduslov":"Objekat drži temperaturu. Ekran je još ne crta.","samostalnoUcenje":{"uvod":"Ova tema razvija Kontrolnu sobu kroz poznat problem. Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem. Pre nego što otvoriš objašnjenje pitalice, napiši sopstvenu pretpostavku, pokreni kod i uporedi stvarni ishod sa očekivanjem.","detaljnoGradivo":["DOM je programski model dokumenta u browseru. Čitanje i izmena JavaScript objekta ne menjaju automatski tekst elementa; neophodno je eksplicitno osvežiti prikaz. Podela na stanje i render smanjuje broj mesta koja manipulišu DOM-om i olakšava razumevanje greške kada ekran ne prati model.","Browser šalje događaje određenim ciljevima; događaj može prolaziti kroz faze capture i bubbling. event.target označava izvor, a currentTarget aktuelni element na čijem se listeneru nalazimo. Delegacija omogućava da jedan listener obrađuje više kontrola, što je naročito korisno kada se dugmad dinamički dodaju.","Listener dobija funkciju, a ne rezultat njenog poziva. Greška addEventListener('click', handler()) obično pokreće handler pri registraciji. U Kontrolnoj sobi klik menja željeno stanje, a odvojena funkcija ažurira displej i natpis prekidača. Kasnije će isti UI slati komandu serveru umesto da sam glumi stvarni ventilator.","Browserov DOM je stablo objekata za prikaz dokumenta, a model aplikacije je naš sopstveni objekat sa temperaturom. Niko automatski ne održava njihovu jednakost u običnom JavaScriptu. Zato organizujemo jednosmerni tok: događaj → logika promene stanja → funkcija za prikaz. Kada vrednosti odstupaju, možemo zasebno proveriti svaki prelaz.","Događaj se ne obrađuje samo 'na dugmetu'. DOM definiše cilj i faze propagacije: capture, target i bubble. event.target govori gde je događaj nastao, a event.currentTarget gde se trenutno obrađuje. Delegacija događaja koristi taj mehanizam za više kontrola. Za dugme u formi vodi računa i o podrazumevanom submit ponašanju.","Klase za Displej i Prekidač ne uvodimo zato što JavaScript zahteva objektno-orijentisani dizajn, nego da odvojimo upravljanje prikazom. Student treba da objasni gde živi zajednička metoda, kako radi this i kakvu grešku dobijamo kada prosledimo odvojenu metodu bez njenog primaoca."],"tokRada":"1) Pročitaj problem i opiši šta očekuješ. 2) Odgovori bez izvršavanja. 3) Otvori detaljno objašnjenje svih opcija. 4) Pokreni primer u izolovanom editoru. 5) Izmeni jedan detalj i ponovi eksperiment. 6) Vrati se Kontrolnoj sobi i poveži naučeno sa njenim fajlovima.","graniceZnanja":"Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem. Pretpostavke o serveru, browseru i bazi moraš navesti eksplicitno; kada zavise od konfiguracije, odgovor nije univerzalan.","proveraRazumevanja":"Na kraju teme navedi jednu pogrešnu pretpostavku koju si promenio, pokaži konkretan red koda ili HTTP zapis koji je razotkriva i objasni kako bi isti problem nastao u Kontrolnoj sobi."},"dodatniPrimeri":[{"id":"04-e01","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Događaj bez poziva","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"button.addEventListener("click", naKlik);","pitanje":"Kada se poziva naKlik?","opcije":[{"key":"A","text":"Samo kada se stranica ponovo učita.","why":"Ova pretpostavka ne važi: Samo kada se stranica ponovo učita. addEventListener prima referencu na funkciju koju browser kasnije poziva kada događaj nastupi. Oblik naKlik() izvršio bi funkciju odmah, a u listener bi bio prosleđen njen rezultat.","ok":false},{"key":"B","text":"Pri kliku, ako je listener uspešno registrovan.","why":"addEventListener prima referencu na funkciju koju browser kasnije poziva kada događaj nastupi. Oblik naKlik() izvršio bi funkciju odmah, a u listener bi bio prosleđen njen rezultat.","ok":true},{"key":"C","text":"Odmah pri registraciji.","why":"Ova pretpostavka ne važi: Odmah pri registraciji. addEventListener prima referencu na funkciju koju browser kasnije poziva kada događaj nastupi. Oblik naKlik() izvršio bi funkciju odmah, a u listener bi bio prosleđen njen rezultat.","ok":false}],"tacanOdgovor":"Pri kliku, ako je listener uspešno registrovan.","objasnjenje":"addEventListener prima referencu na funkciju koju browser kasnije poziva kada događaj nastupi. Oblik naKlik() izvršio bi funkciju odmah, a u listener bi bio prosleđen njen rezultat. Zato razlika između funkcije kao vrednosti i poziva funkcije utiče na vreme izvršavanja, ne samo na sintaksu.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem.","ocekivaniRezultat":"Pri kliku, ako je listener uspešno registrovan.","pripremaTestOkruzenja":"const button=document.createElement("button"); const naKlik=()=>console.log("klik"); document.body.append(button);"},{"id":"04-e02","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"DOM nije model","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"const soba={t:24};
soba.t=25;
console.log(document.querySelector("#temp").textContent);","pitanje":"Ako je u HTML-u <span id="temp">24</span>, šta piše na ekranu?","opcije":[{"key":"A","text":"24, jer izmena objekta sama ne menja DOM.","why":"Promenljiva soba i DOM element su dva odvojena objekta. Browser ne zna da soba.t odgovara tekstu elementa #temp.","ok":true},{"key":"B","text":"25, jer se DOM automatski sinhronizuje.","why":"Ova pretpostavka ne važi: 25, jer se DOM automatski sinhronizuje. Promenljiva soba i DOM element su dva odvojena objekta. Browser ne zna da soba.t odgovara tekstu elementa #temp.","ok":false},{"key":"C","text":"Prazan tekst, jer je model promenjen.","why":"Ova pretpostavka ne važi: Prazan tekst, jer je model promenjen. Promenljiva soba i DOM element su dva odvojena objekta. Browser ne zna da soba.t odgovara tekstu elementa #temp.","ok":false}],"tacanOdgovor":"24, jer izmena objekta sama ne menja DOM.","objasnjenje":"Promenljiva soba i DOM element su dva odvojena objekta. Browser ne zna da soba.t odgovara tekstu elementa #temp. Potreban je eksplicitan render, na primer element.textContent=String(soba.t), ili mehanizam reaktivnosti koji takav render organizuje. Ovo je ključna granica između modela i prikaza.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem.","ocekivaniRezultat":"24, jer izmena objekta sama ne menja DOM.","pripremaTestOkruzenja":"<span id="temp">24</span>"},{"id":"04-e03","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Bubbling i delegacija","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"list.addEventListener("click", e=>console.log(e.target.tagName));
// korisnik klikne BUTTON unutar list","pitanje":"Šta e.target obično pokazuje?","opcije":[{"key":"A","text":"Uvek LIST jer je listener na list.","why":"Ova pretpostavka ne važi: Uvek LIST jer je listener na list. Listener je registrovan na roditelju list, ali target upućuje na element na kome je događaj nastao. currentTarget je element na kome se trenutno izvršava listener. To omogućava delegaciju događaja: jedan listener na panelu može da obrađuje više prekidača i dugmadi, umesto da za svako dinamički dodato dugme registrujemo zasebnu funkciju.","ok":false},{"key":"B","text":"Uvek BODY jer događaj prolazi kroz dokument.","why":"Ova pretpostavka ne važi: Uvek BODY jer događaj prolazi kroz dokument. Listener je registrovan na roditelju list, ali target upućuje na element na kome je događaj nastao. currentTarget je element na kome se trenutno izvršava listener. To omogućava delegaciju događaja: jedan listener na panelu može da obrađuje više prekidača i dugmadi, umesto da za svako dinamički dodato dugme registrujemo zasebnu funkciju.","ok":false},{"key":"C","text":"BUTTON na koji je korisnik kliknuo.","why":"Listener je registrovan na roditelju list, ali target upućuje na element na kome je događaj nastao. currentTarget je element na kome se trenutno izvršava listener. To omogućava delegaciju događaja: jedan listener na panelu može da obrađuje više prekidača i dugmadi, umesto da za svako dinamički dodato dugme registrujemo zasebnu funkciju.","ok":true}],"tacanOdgovor":"BUTTON na koji je korisnik kliknuo.","objasnjenje":"Listener je registrovan na roditelju list, ali target upućuje na element na kome je događaj nastao. currentTarget je element na kome se trenutno izvršava listener. To omogućava delegaciju događaja: jedan listener na panelu može da obrađuje više prekidača i dugmadi, umesto da za svako dinamički dodato dugme registrujemo zasebnu funkciju.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem.","ocekivaniRezultat":"BUTTON na koji je korisnik kliknuo.","pripremaTestOkruzenja":"const list=document.createElement("div"); list.innerHTML="<button>Uključi</button>"; document.body.append(list);"},{"id":"04-e04","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Pogrešan callback","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"function ukljuci(){console.log("klik")}
dugme.addEventListener("click", ukljuci());","pitanje":"Zašto se „klik” ispisuje pri učitavanju i kako ispraviti kod?","opcije":[{"key":"A","text":"Dodaj await ispred addEventListener.","why":"Ova pretpostavka ne važi: Dodaj await ispred addEventListener. Zagrade pozivaju funkciju u trenutku evaluacije izraza. addEventListener zatim prima povratnu vrednost, ovde undefined, a ne callback. Ispravno je addEventListener("click", ukljuci).","ok":false},{"key":"B","text":"ukljuci() se odmah izvršava; prosledi funkciju ukljuci.","why":"Zagrade pozivaju funkciju u trenutku evaluacije izraza. addEventListener zatim prima povratnu vrednost, ovde undefined, a ne callback. Ispravno je addEventListener("click", ukljuci).","ok":true},{"key":"C","text":"Browser automatski izvršava svaki click događaj.","why":"Ova pretpostavka ne važi: Browser automatski izvršava svaki click događaj. Zagrade pozivaju funkciju u trenutku evaluacije izraza. addEventListener zatim prima povratnu vrednost, ovde undefined, a ne callback. Ispravno je addEventListener("click", ukljuci).","ok":false}],"tacanOdgovor":"ukljuci() se odmah izvršava; prosledi funkciju ukljuci.","objasnjenje":"Zagrade pozivaju funkciju u trenutku evaluacije izraza. addEventListener zatim prima povratnu vrednost, ovde undefined, a ne callback. Ispravno je addEventListener("click", ukljuci). Posle izmene uporedi konzolu pre i posle stvarnog klika: time potvrđuješ da je radnja odložena do događaja.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Korisnički događaj menja aplikaciono stanje tek kada ga obradi listener; poseban korak mora uskladiti DOM sa novim stanjem.","ocekivaniRezultat":"ukljuci() se odmah izvršava; prosledi funkciju ukljuci.","predlogPopravke":"dugme.addEventListener("click", ukljuci);","pripremaTestOkruzenja":"const dugme=document.createElement("button"); document.body.append(dugme);","provera-popravke":"potrebna"},{"id":"04-r01","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Capture i bubble","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"const el=document.createElement("div");
const btn=document.createElement("button"); el.append(btn);
el.addEventListener("click",()=>console.log("capture"),true);
btn.addEventListener("click",()=>console.log("target"));
el.addEventListener("click",()=>console.log("bubble"));
btn.click();","pitanje":"Koji je redosled ispisa?","opcije":[{"key":"A","text":"target capture bubble","why":"Ne važi tvrdnja „target capture bubble”. Događaj prolazi kroz capture fazu od roditelja ka cilju, zatim se obrađuje na ciljnom button elementu, pa kroz bubble fazu nazad ka roditelju.","ok":false},{"key":"B","text":"capture target bubble","why":"Tačan zaključak. Događaj prolazi kroz capture fazu od roditelja ka cilju, zatim se obrađuje na ciljnom button elementu, pa kroz bubble fazu nazad ka roditelju. Program eksplicitno poziva click(), tako da je rezultat u ovom DOM primeru determinističan.","ok":true},{"key":"C","text":"bubble target capture","why":"Ne važi tvrdnja „bubble target capture”. Događaj prolazi kroz capture fazu od roditelja ka cilju, zatim se obrađuje na ciljnom button elementu, pa kroz bubble fazu nazad ka roditelju.","ok":false}],"tacanOdgovor":"capture target bubble","objasnjenje":"Događaj prolazi kroz capture fazu od roditelja ka cilju, zatim se obrađuje na ciljnom button elementu, pa kroz bubble fazu nazad ka roditelju. Program eksplicitno poziva click(), tako da je rezultat u ovom DOM primeru determinističan.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"capture target bubble","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"04-r02","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Tekst ostaje star","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"const model={t:24};
const el=document.createElement("span"); el.textContent="24";
model.t=27;
console.log(model.t,el.textContent);","pitanje":"Šta se ispisuje?","opcije":[{"key":"A","text":"27 24","why":"Tačan zaključak. JS model i DOM su nezavisne strukture. Dodela model.t=27 ne poziva automatski render. Tek el.textContent=String(model.t) prenosi stanje u prikaz. Ovaj raskorak namerno izazivamo da bismo videli zašto je potreban poseban korak renderovanja.","ok":true},{"key":"B","text":"27 27","why":"Ne važi tvrdnja „27 27”. JS model i DOM su nezavisne strukture.","ok":false},{"key":"C","text":"24 24","why":"Ne važi tvrdnja „24 24”. JS model i DOM su nezavisne strukture.","ok":false}],"tacanOdgovor":"27 24","objasnjenje":"JS model i DOM su nezavisne strukture. Dodela model.t=27 ne poziva automatski render. Tek el.textContent=String(model.t) prenosi stanje u prikaz. Ovaj raskorak namerno izazivamo da bismo videli zašto je potreban poseban korak renderovanja.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"27 24","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"04-r03","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Slušalac pozvan prerano","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"function stanje(){console.log("klik")};
const b=document.createElement("button");
b.addEventListener("click",stanje());","pitanje":"Zašto se „klik” ispisuje odmah, pre bilo kog događaja?","opcije":[{"key":"A","text":"Potreban je await ispred addEventListener","why":"Ne važi tvrdnja „Potreban je await ispred addEventListener”. Zagrade u argumentu funkcije znače izvršavanje sada, pre poziva addEventListener.","ok":false},{"key":"B","text":"Dugme treba da bude input umesto button","why":"Ne važi tvrdnja „Dugme treba da bude input umesto button”. Zagrade u argumentu funkcije znače izvršavanje sada, pre poziva addEventListener.","ok":false},{"key":"C","text":"Poziva se stanje() pri registraciji; treba predati stanje.","why":"Tačan zaključak. Zagrade u argumentu funkcije znače izvršavanje sada, pre poziva addEventListener. Povratna vrednost ove funkcije je undefined, pa nije registrovan handler za kasniji klik. Ispravno se prosleđuje sama funkcija kao vrednost.","ok":true}],"tacanOdgovor":"Poziva se stanje() pri registraciji; treba predati stanje.","objasnjenje":"Zagrade u argumentu funkcije znače izvršavanje sada, pre poziva addEventListener. Povratna vrednost ove funkcije je undefined, pa nije registrovan handler za kasniji klik. Ispravno se prosleđuje sama funkcija kao vrednost.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"Poziva se stanje() pri registraciji; treba predati stanje.","predlogPopravke":"b.addEventListener("click", stanje); b.click(); // klik","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema","provera-popravke":"potrebna"}]}

