korak.dopunska-polja:
{"tipPrimer":"eksperiment","samostalniPrimer":{"jezik":"sql","izolovan":true,"tekst":"BEGIN;
UPDATE ventilator SET ukljucen=true WHERE id=1;
INSERT INTO istorija(komanda) VALUES ('on');
COMMIT;"},"analizaPitalice":"Ako proces prekine rad pre COMMIT-a, nepotvrđena transakcija se ne zadržava kao uspešan upis. Ako se proces prekine posle COMMIT-a, a pre odgovora, klijent ne zna ishod i mora ga proveriti."}

pojam.zapis:
BEGIN;
UPDATE ventilator SET ukljucen = $1;
INSERT INTO istorija(komanda) VALUES ($2);
COMMIT;

nedelja.dopunska-polja:
{"predavanjeMinuta":55,"diskusijaMinuta":35,"samostalniZadaci":"van-casa","preduslov":"Režim i istorija su jedna transakcija.","samostalnoUcenje":{"uvod":"Ova tema razvija Kontrolnu sobu kroz poznat problem. Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise. Pre nego što otvoriš objašnjenje pitalice, napiši sopstvenu pretpostavku, pokreni kod i uporedi stvarni ishod sa očekivanjem.","detaljnoGradivo":["Kada server sam menja temperaturu, poslednji broj na browser displeju nije nužno trenutno očitavanje. Očitavanje zato treba da nosi i trenutak ili monotono rastuću verziju. Broj koji je stigao poslednji ne mora biti najnoviji: ranije poslati zahtev može završiti kasnije i prepisati noviji rezultat.","Periodično čitanje (polling) je najjednostavnije rešenje za osvežavanje, ali setInterval ne čeka da se prethodni Promise završi. Preklapanje zahteva povećava opterećenje i uvodi redosledne trke. Izbor intervala zavisi od zahteva za svežinom, kašnjenja i količine klijenata. Odbacivanje starijih verzija rešava jednu klasu grešaka, ali ne sve slučajeve konkurentnosti.","Cache ubrzava ponavljanje zahteva kada su podaci dovoljno sveži: ikonica i temperatura ne zahtevaju istu politiku. Push pristupi, poput SSE ili WebSocket-a, mogu smanjiti potrebu za ponavljanim čitanjem, ali uvode pitanja prekida veze, ponovnog povezivanja i redosleda događaja. U Kontrolnoj sobi student poredi ove pristupe sa konkretnim prikazom temperature.","Poslednje primljeno očitavanje nije automatski najnovije nastalo očitavanje. Kod dva paralelna HTTP zahteva odgovor sa ranijim vremenom merenja može stići poslednji. Verzija očitavanja ili pažljivo tumačen server timestamp pomaže da UI odbaci stariju vrednost, ali zahteva dogovor o poreklu i poređenju podataka.","Polling daje jednostavan kanal: browser ponavlja GET u određenom intervalu. Trošak zavisi od broja klijenata, brzine promene i dužine intervala. setInterval može izazvati preklapanje; ako zahtev traje duže od perioda, sledeći kreće pre završetka prvog. Serijski raspored i kontrola in-flight zahteva smanjuju taj problem.","SSE i WebSocket mogu potiskivati promene bez svakog novog zahteva, ali se moraju rešiti reconnect, izgubljeni događaji, autorizacija i početna sinhronizacija. Cache statičke ikonice i temperature imaju različite zahteve za svežinom. U Kontrolnoj sobi vrednost, trenutak i status svežine treba prikazati kao tri odvojene informacije."],"tokRada":"1) Pročitaj problem i opiši šta očekuješ. 2) Odgovori bez izvršavanja. 3) Otvori detaljno objašnjenje svih opcija. 4) Pokreni primer u izolovanom editoru. 5) Izmeni jedan detalj i ponovi eksperiment. 6) Vrati se Kontrolnoj sobi i poveži naučeno sa njenim fajlovima.","graniceZnanja":"Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise. Pretpostavke o serveru, browseru i bazi moraš navesti eksplicitno; kada zavise od konfiguracije, odgovor nije univerzalan.","proveraRazumevanja":"Na kraju teme navedi jednu pogrešnu pretpostavku koju si promenio, pokaži konkretan red koda ili HTTP zapis koji je razotkriva i objasni kako bi isti problem nastao u Kontrolnoj sobi."},"dodatniPrimeri":[{"id":"09-e01","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Stari odgovor","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"Odgovor B: vrednost=26, timestamp=12:05, stiže prvi
Odgovor A: vrednost=24, timestamp=12:04, stiže drugi","pitanje":"Koji broj treba zadržati?","opcije":[{"key":"A","text":"24, jer je poslednji stigao.","why":"Ova pretpostavka ne važi: 24, jer je poslednji stigao. Stigao poslednji nije isto što i izmeren poslednji. Ako klijent čuva poslednji prihvaćeni timestamp, može odbaciti A, iako je A kasnije stigao.","ok":false},{"key":"B","text":"Oba broja sabrati.","why":"Ova pretpostavka ne važi: Oba broja sabrati. Stigao poslednji nije isto što i izmeren poslednji. Ako klijent čuva poslednji prihvaćeni timestamp, može odbaciti A, iako je A kasnije stigao.","ok":false},{"key":"C","text":"26, jer ima noviji trenutak očitavanja.","why":"Stigao poslednji nije isto što i izmeren poslednji. Ako klijent čuva poslednji prihvaćeni timestamp, može odbaciti A, iako je A kasnije stigao.","ok":true}],"tacanOdgovor":"26, jer ima noviji trenutak očitavanja.","objasnjenje":"Stigao poslednji nije isto što i izmeren poslednji. Ako klijent čuva poslednji prihvaćeni timestamp, može odbaciti A, iako je A kasnije stigao. Time se sprečava vraćanje prikaza unazad. U stvarnom sistemu treba razmotriti i pouzdanost satova, pa monotona verzija sa servera često daje jednostavniji ugovor.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise.","ocekivaniRezultat":"26, jer ima noviji trenutak očitavanja."},{"id":"09-e02","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"izolovano","okruzenje":"javascript-izolovano","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Interval i preklapanje","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"let aktivni = 0;
async function procitaj() {
 aktivni++;
 await new Promise(resolve => setTimeout(resolve, 80));
 aktivni--;
}
const tajmer = setInterval(procitaj, 20);
setTimeout(() => {
 clearInterval(tajmer);
 console.log(aktivni);
}, 55);","pitanje":"Koliko istovremenih čitanja može nastati?","opcije":[{"key":"A","text":"Nijedno, jer async funkcije blokiraju event loop.","why":"Ova pretpostavka ne važi: Nijedno, jer async funkcije blokiraju event loop. setInterval zakazuje callback po intervalu, ali ne čeka da se asinhroni zahtev završi. Ako mrežni zahtev traje duže od intervala, nastaju preklopljeni zahtevi, veće opterećenje i odgovori van redosleda.","ok":false},{"key":"B","text":"Više od jednog, jer setInterval ne čeka Promise.","why":"setInterval zakazuje callback po intervalu, ali ne čeka da se asinhroni zahtev završi. Ako mrežni zahtev traje duže od intervala, nastaju preklopljeni zahtevi, veće opterećenje i odgovori van redosleda.","ok":true},{"key":"C","text":"Tačno jedno, svaki interval automatski čeka await.","why":"Ova pretpostavka ne važi: Tačno jedno, svaki interval automatski čeka await. setInterval zakazuje callback po intervalu, ali ne čeka da se asinhroni zahtev završi. Ako mrežni zahtev traje duže od intervala, nastaju preklopljeni zahtevi, veće opterećenje i odgovori van redosleda.","ok":false}],"tacanOdgovor":"Više od jednog, jer setInterval ne čeka Promise.","objasnjenje":"setInterval zakazuje callback po intervalu, ali ne čeka da se asinhroni zahtev završi. Ako mrežni zahtev traje duže od intervala, nastaju preklopljeni zahtevi, veće opterećenje i odgovori van redosleda. Rešenje može biti zaštitni flag, abort prethodnog zahteva ili setTimeout tek po završetku prethodnog čitanja. Izbor zavisi od cilja svežine i opterećenja.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise.","ocekivaniRezultat":"2 u datom eksperimentu; setInterval može pokrenuti drugo čitanje pre nego što prvo završi."},{"id":"09-e03","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Cache temperatura i ikonica","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"GET /icon.svg (Cache-Control: max-age=86400)
GET /api/soba (Cache-Control: no-store)","pitanje":"Zašto ista cache politika nije dobra za oba resursa?","opcije":[{"key":"A","text":"Ikonica je uglavnom stabilna, temperatura se često menja.","why":"Cache smanjuje mrežni rad samo ako ponovna upotreba odgovora ne narušava očekivanu svežinu. Ikonica može bez problema ostati ista ceo dan, dok očitavanje mora odražavati najnovije prihvatljivo stanje ili imati jasno navedenu starost. no-store sprečava skladištenje, a za drugačije potrebe mogu se koristiti uslovni zahtevi i revalidacija.","ok":true},{"key":"B","text":"Oba odgovora su HTTP pa moraju imati isti rok.","why":"Ova pretpostavka ne važi: Oba odgovora su HTTP pa moraju imati isti rok. Cache smanjuje mrežni rad samo ako ponovna upotreba odgovora ne narušava očekivanu svežinu. Ikonica može bez problema ostati ista ceo dan, dok očitavanje mora odražavati najnovije prihvatljivo stanje ili imati jasno navedenu starost. no-store sprečava skladištenje, a za drugačije potrebe mogu se koristiti uslovni zahtevi i revalidacija.","ok":false},{"key":"C","text":"Temperatura je broj pa joj cache nije potreban za ikad.","why":"Ova pretpostavka ne važi: Temperatura je broj pa joj cache nije potreban za ikad. Cache smanjuje mrežni rad samo ako ponovna upotreba odgovora ne narušava očekivanu svežinu. Ikonica može bez problema ostati ista ceo dan, dok očitavanje mora odražavati najnovije prihvatljivo stanje ili imati jasno navedenu starost. no-store sprečava skladištenje, a za drugačije potrebe mogu se koristiti uslovni zahtevi i revalidacija.","ok":false}],"tacanOdgovor":"Ikonica je uglavnom stabilna, temperatura se često menja.","objasnjenje":"Cache smanjuje mrežni rad samo ako ponovna upotreba odgovora ne narušava očekivanu svežinu. Ikonica može bez problema ostati ista ceo dan, dok očitavanje mora odražavati najnovije prihvatljivo stanje ili imati jasno navedenu starost. no-store sprečava skladištenje, a za drugačije potrebe mogu se koristiti uslovni zahtevi i revalidacija. O izboru odlučuje značenje podataka, ne MIME tip.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise.","ocekivaniRezultat":"Ikonica je uglavnom stabilna, temperatura se često menja."},{"id":"09-e04","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Push nije autorizacija","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"SSE: server šalje event: temperatura
data: {"t":25}","pitanje":"Da li sama upotreba SSE znači da korisnik sme izdavati komande?","opcije":[{"key":"A","text":"Da, SSE automatski dodeljuje ulogu operatera.","why":"Ova pretpostavka ne važi: Da, SSE automatski dodeljuje ulogu operatera. SSE može slati događaje sa servera ka browseru bez ponavljanog HTTP čitanja, ali ne menja pravila identiteta i autorizacije. Čitanje i upravljanje su zasebne dozvole.","ok":false},{"key":"B","text":"Da, push znači da server veruje svakom klijentu.","why":"Ova pretpostavka ne važi: Da, push znači da server veruje svakom klijentu. SSE može slati događaje sa servera ka browseru bez ponavljanog HTTP čitanja, ali ne menja pravila identiteta i autorizacije. Čitanje i upravljanje su zasebne dozvole.","ok":false},{"key":"C","text":"Ne. Kanal ažuriranja i pravo na komandu su odvojeni.","why":"SSE može slati događaje sa servera ka browseru bez ponavljanog HTTP čitanja, ali ne menja pravila identiteta i autorizacije. Čitanje i upravljanje su zasebne dozvole.","ok":true}],"tacanOdgovor":"Ne. Kanal ažuriranja i pravo na komandu su odvojeni.","objasnjenje":"SSE može slati događaje sa servera ka browseru bez ponavljanog HTTP čitanja, ali ne menja pravila identiteta i autorizacije. Čitanje i upravljanje su zasebne dozvole. Tok događaja treba razumeti i kroz prekide, ponovno povezivanje i eventualno redosled poruka, a ne samo kao zgodniju zamenu za polling.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Svežina se meri trenutkom ili verzijom očitavanja, a ne redosledom dolaska. Polling, cache i push imaju različite kompromise.","ocekivaniRezultat":"Ne. Kanal ažuriranja i pravo na komandu su odvojeni."},{"id":"09-r01","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Odgovor kasni, ali merenje je starije","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"A: version=7 temperatura=24, stiže u 10:00:03
B: version=8 temperatura=26, stiže u 10:00:02","pitanje":"Koja vrednost treba da ostane na displeju?","opcije":[{"key":"A","text":"24, jer odgovor A stiže poslednji","why":"Ne važi tvrdnja „24, jer odgovor A stiže poslednji”. Redosled prispeća HTTP odgovora ne određuje redosled nastanka očitavanja.","ok":false},{"key":"B","text":"26, jer verzija 8 označava novije očitavanje.","why":"Tačan zaključak. Redosled prispeća HTTP odgovora ne određuje redosled nastanka očitavanja. Ako version raste za svako novo merenje, klijent može zadržati najveću viđenu verziju i odbaciti kasno pristigli stariji rezultat.","ok":true},{"key":"C","text":"24, jer je broj manji i zato stariji","why":"Ne važi tvrdnja „24, jer je broj manji i zato stariji”. Redosled prispeća HTTP odgovora ne određuje redosled nastanka očitavanja.","ok":false}],"tacanOdgovor":"26, jer verzija 8 označava novije očitavanje.","objasnjenje":"Redosled prispeća HTTP odgovora ne određuje redosled nastanka očitavanja. Ako version raste za svako novo merenje, klijent može zadržati najveću viđenu verziju i odbaciti kasno pristigli stariji rezultat.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"26, jer verzija 8 označava novije očitavanje.","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"09-r02","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"izolovano","okruzenje":"javascript-izolovano","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Dva preklopljena poziva","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"let aktivni=0;
async function citaj(){aktivni++; await new Promise(r=>setTimeout(r,20)); aktivni--;}
citaj(); citaj();
console.log(aktivni);","pitanje":"Šta će se prvo ispisati?","opcije":[{"key":"A","text":"2","why":"Tačan zaključak. Pozivanje async funkcije izvršava početni sinhroni deo odmah, do prvog await. Zato oba poziva povećaju aktivni pre nego što console.log pročita vrednost. Nakon odlaganja Promise nastavlja svaki poziv i smanjuje brojač. Ovo pokazuje da await ne sprečava preklapanje.","ok":true},{"key":"B","text":"0","why":"Ne važi tvrdnja „0”. Pozivanje async funkcije izvršava početni sinhroni deo odmah, do prvog await.","ok":false},{"key":"C","text":"1","why":"Ne važi tvrdnja „1”. Pozivanje async funkcije izvršava početni sinhroni deo odmah, do prvog await.","ok":false}],"tacanOdgovor":"2","objasnjenje":"Pozivanje async funkcije izvršava početni sinhroni deo odmah, do prvog await. Zato oba poziva povećaju aktivni pre nego što console.log pročita vrednost. Nakon odlaganja Promise nastavlja svaki poziv i smanjuje brojač. Ovo pokazuje da await ne sprečava preklapanje.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"2","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"09-r03","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Pogrešno poređenje vremena","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"const poznataVerzija = 12;
const prikazi = v => console.log(v);
const odgovor = {version:11, temperatura:22};
prikazi(odgovor.temperatura); // staro merenje pregazi prikaz","pitanje":"Kako sprečiti da starije očitavanje pregazi novije?","opcije":[{"key":"A","text":"Zameniti version brojem temperature","why":"Ne važi tvrdnja „Zameniti version brojem temperature”. Najnovija pristigla poruka nije nužno najnovije merenje.","ok":false},{"key":"B","text":"Uvek prihvatiti poslednji odgovor koji je stigao","why":"Ne važi tvrdnja „Uvek prihvatiti poslednji odgovor koji je stigao”. Najnovija pristigla poruka nije nužno najnovije merenje.","ok":false},{"key":"C","text":"Proveriti version pre prikazi i odbaciti verziju 11.","why":"Tačan zaključak. Najnovija pristigla poruka nije nužno najnovije merenje. Monotona server verzija omogućava jasno poređenje čak i kada se vremena klijenata razlikuju. Ako odgovor.version < poznataVerzija, prikaz ne treba menjati.","ok":true}],"tacanOdgovor":"Proveriti version pre prikazi i odbaciti verziju 11.","objasnjenje":"Najnovija pristigla poruka nije nužno najnovije merenje. Monotona server verzija omogućava jasno poređenje čak i kada se vremena klijenata razlikuju. Ako odgovor.version < poznataVerzija, prikaz ne treba menjati.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"Proveriti version pre prikazi i odbaciti verziju 11.","predlogPopravke":"if (odgovor.version >= poznataVerzija) prikazi(odgovor.temperatura);","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema","provera-popravke":"potrebna"}]}

korak.dopunska-polja:
{"tipPrimer":"pitalica-kod","samostalniPrimer":{"jezik":"text","izolovan":true,"tekst":"A: {t:24, version:10} // stiže poslednji
B: {t:25, version:11} // stiže prvi
// ekran čuva najveću poznatu verziju"},"dijagram":{"format":"text","tekst":"zahtev A ─────────── odgovor v10
 zahtev B ─ odgovor v11"},"analizaPitalice":"Vreme merenja i vreme dolaska nisu isto. Ako očitavanje B nastane kasnije ali stigne ranije, kasnije pristigli A ne sme prepisati B samo zato što je poslednji mrežni odgovor."}

nedelja.dopunska-polja:
{"predavanjeMinuta":55,"diskusijaMinuta":35,"samostalniZadaci":"van-casa","preduslov":"Displej čuva poslednje čitanje. Takt ga ne pomera.","samostalnoUcenje":{"uvod":"Ova tema razvija Kontrolnu sobu kroz poznat problem. Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande. Pre nego što otvoriš objašnjenje pitalice, napiši sopstvenu pretpostavku, pokreni kod i uporedi stvarni ishod sa očekivanjem.","detaljnoGradivo":["Autentifikacija odgovara na pitanje ko je klijent; autorizacija na pitanje šta sme da radi. U Kontrolnoj sobi posmatrač čita stanje, a operater sme da izdaje komande. Sakrivanje dugmeta u browseru nije zaštita: bilo koji HTTP klijent može formirati zahtev, pa server mora proveravati pravo na svaku mutirajuću operaciju.","Sesijski cookie može nositi neprozirni token koji server mapira na ulogu. HttpOnly sprečava direktno čitanje njegove vrednosti preko JavaScripta; Secure ograničava slanje na HTTPS, a SameSite utiče na slanje u cross-site kontekstima. Nijedan od tih atributa sam ne rešava sve probleme bezbednosti. CORS reguliše pristup browser skripte cross-origin odgovorima i nije zamena za autorizaciju.","XSS nastaje kada nepouzdan sadržaj postane izvršiv HTML ili JavaScript. Za običan tekst koristimo textContent umesto innerHTML. CSRF zahteva posebnu procenu kod zahteva koji koriste automatski poslate akreditive. Studenti treba da razlikuju zaštite browsera, provere na serveru i zahteve API ugovora, umesto da pamte samo statuse 401 i 403.","Razlikuj identitet od prava: autentifikacija utvrđuje ko šalje zahtev, autorizacija odlučuje koju operaciju sme. Posmatrač ima pravo na čitanje, a operater na komandu. Skrivanje dugmeta u browseru menja UX, ali ne sprečava slanje PUT zahteva iz drugog klijenta.","HttpOnly smanjuje izlaganje cookie vrednosti JavaScriptu, Secure vezuje slanje za HTTPS, a SameSite utiče na cross-site ponašanje. Nijedan atribut nije potpuna odbrana od svih napada. CORS ograničava pristup odgovoru browser skripte i ne može da zameni server-side autorizaciju.","Na konkretnoj prijavi napada analiziraj granicu poverenja. Ako server veruje ulogi poslatoj iz JSON-a, korisnik može sam sebi dati više prava. Ako nepouzdan tekst ubaci kroz innerHTML, može postati aktivan HTML. Ako cookie ide automatski, postoji i problem CSRF-a. Za svaku pretnju definiši ulaz, uslov i ciljanu zaštitu."],"tokRada":"1) Pročitaj problem i opiši šta očekuješ. 2) Odgovori bez izvršavanja. 3) Otvori detaljno objašnjenje svih opcija. 4) Pokreni primer u izolovanom editoru. 5) Izmeni jedan detalj i ponovi eksperiment. 6) Vrati se Kontrolnoj sobi i poveži naučeno sa njenim fajlovima.","graniceZnanja":"Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande. Pretpostavke o serveru, browseru i bazi moraš navesti eksplicitno; kada zavise od konfiguracije, odgovor nije univerzalan.","proveraRazumevanja":"Na kraju teme navedi jednu pogrešnu pretpostavku koju si promenio, pokaži konkretan red koda ili HTTP zapis koji je razotkriva i objasni kako bi isti problem nastao u Kontrolnoj sobi."},"dodatniPrimeri":[{"id":"10-e01","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Sakriveno dugme","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"document.querySelector("#ukljuci").hidden=true;
// drugi klijent pošalje PUT /api/ventilator","pitanje":"Da li sakriveno dugme štiti API?","opcije":[{"key":"A","text":"Da, hidden menja dozvole u HTTP-u.","why":"Ova pretpostavka ne važi: Da, hidden menja dozvole u HTTP-u. DOM je pod kontrolom klijenta i ne predstavlja granicu poverenja. Skriveno dugme samo uklanja UI mogućnost, ali HTTP zahtev može doći iz terminala, drugog browsera ili prilagođenog programa.","ok":false},{"key":"B","text":"Ne. Server mora da proveri pravo pristupa za svaki zahtev.","why":"DOM je pod kontrolom klijenta i ne predstavlja granicu poverenja. Skriveno dugme samo uklanja UI mogućnost, ali HTTP zahtev može doći iz terminala, drugog browsera ili prilagođenog programa.","ok":true},{"key":"C","text":"Da, drugi klijent ne može napraviti PUT.","why":"Ova pretpostavka ne važi: Da, drugi klijent ne može napraviti PUT. DOM je pod kontrolom klijenta i ne predstavlja granicu poverenja. Skriveno dugme samo uklanja UI mogućnost, ali HTTP zahtev može doći iz terminala, drugog browsera ili prilagođenog programa.","ok":false}],"tacanOdgovor":"Ne. Server mora da proveri pravo pristupa za svaki zahtev.","objasnjenje":"DOM je pod kontrolom klijenta i ne predstavlja granicu poverenja. Skriveno dugme samo uklanja UI mogućnost, ali HTTP zahtev može doći iz terminala, drugog browsera ili prilagođenog programa. Server mora iz sesije izvesti identitet i ulogu i proveriti dozvole pre menjanja režima uređaja.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande.","ocekivaniRezultat":"Ne. Server mora da proveri pravo pristupa za svaki zahtev.","pripremaTestOkruzenja":"<button id="ukljuci">Uključi</button>"},{"id":"10-e02","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"HttpOnly nije CSRF zaštita","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"Set-Cookie: sesija=token; HttpOnly; Secure; SameSite=Lax","pitanje":"Koji rizik HttpOnly prvenstveno umanjuje?","opcije":[{"key":"A","text":"JavaScript na stranici ne može direktno pročitati vrednost cookie-ja.","why":"HttpOnly zabranjuje direktno čitanje vrednosti cookie-ja preko document.cookie, ali ne eliminiše sve posledice XSS-a: ubačeni kod može u nekim okolnostima slati zahteve kao korisnik. Secure ograničava slanje na siguran transport, a SameSite utiče na slanje u cross-site kontekstima.","ok":true},{"key":"B","text":"Potpuno sprečava sve XSS napade.","why":"Ova pretpostavka ne važi: Potpuno sprečava sve XSS napade. HttpOnly zabranjuje direktno čitanje vrednosti cookie-ja preko document.cookie, ali ne eliminiše sve posledice XSS-a: ubačeni kod može u nekim okolnostima slati zahteve kao korisnik. Secure ograničava slanje na siguran transport, a SameSite utiče na slanje u cross-site kontekstima.","ok":false},{"key":"C","text":"Samostalno rešava svaki CSRF napad.","why":"Ova pretpostavka ne važi: Samostalno rešava svaki CSRF napad. HttpOnly zabranjuje direktno čitanje vrednosti cookie-ja preko document.cookie, ali ne eliminiše sve posledice XSS-a: ubačeni kod može u nekim okolnostima slati zahteve kao korisnik. Secure ograničava slanje na siguran transport, a SameSite utiče na slanje u cross-site kontekstima.","ok":false}],"tacanOdgovor":"JavaScript na stranici ne može direktno pročitati vrednost cookie-ja.","objasnjenje":"HttpOnly zabranjuje direktno čitanje vrednosti cookie-ja preko document.cookie, ali ne eliminiše sve posledice XSS-a: ubačeni kod može u nekim okolnostima slati zahteve kao korisnik. Secure ograničava slanje na siguran transport, a SameSite utiče na slanje u cross-site kontekstima. Za zaštitu mutirajućih zahteva potrebna je promišljena CSRF strategija.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande.","ocekivaniRezultat":"JavaScript na stranici ne može direktno pročitati vrednost cookie-ja."},{"id":"10-e03","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"CORS nije login","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"Browser: CORS blocked
curl: HTTP 200 + JSON","pitanje":"Šta je dokazano?","opcije":[{"key":"A","text":"CORS je bezbedna zamena za autorizaciju.","why":"Ova pretpostavka ne važi: CORS je bezbedna zamena za autorizaciju. CORS je mehanizam browsera koji uređuje dostupnost odgovora skriptama sa drugih origin-a; nije mehanizam autentifikacije. Alat kao curl ne sprovodi ista browser ograničenja.","ok":false},{"key":"B","text":"Server uopšte nije odgovorio.","why":"Ova pretpostavka ne važi: Server uopšte nije odgovorio. CORS je mehanizam browsera koji uređuje dostupnost odgovora skriptama sa drugih origin-a; nije mehanizam autentifikacije. Alat kao curl ne sprovodi ista browser ograničenja.","ok":false},{"key":"C","text":"Browser je blokirao čitanje odgovora za dati origin; API nije nužno zaštićen.","why":"CORS je mehanizam browsera koji uređuje dostupnost odgovora skriptama sa drugih origin-a; nije mehanizam autentifikacije. Alat kao curl ne sprovodi ista browser ograničenja.","ok":true}],"tacanOdgovor":"Browser je blokirao čitanje odgovora za dati origin; API nije nužno zaštićen.","objasnjenje":"CORS je mehanizam browsera koji uređuje dostupnost odgovora skriptama sa drugih origin-a; nije mehanizam autentifikacije. Alat kao curl ne sprovodi ista browser ograničenja. Ako API vraća poverljive podatke bez provere pristupa, CORS zaglavlje neće ispraviti taj propust. Uvek razlikuj browser policy od serverske provere korisnika.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande.","ocekivaniRezultat":"Browser je blokirao čitanje odgovora za dati origin; API nije nužno zaštićen."},{"id":"10-e04","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"XSS kroz innerHTML","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"const korisnik="<img src=x onerror=alert(1)>";
element.innerHTML=korisnik;","pitanje":"Kako prikazati korisnički tekst bez interpretiranja kao HTML?","opcije":[{"key":"A","text":"CORS blokira izvršavanje HTML sadržaja.","why":"Ova pretpostavka ne važi: CORS blokira izvršavanje HTML sadržaja. innerHTML parsira primljeni niz kao HTML; nepouzdan unos zato može postati markup sa aktivnim sadržajem. Kada cilj nije interpretacija HTML-a, textContent prikazuje doslovan tekst i ne stvara elemente niti event handlere iz sadržaja.","ok":false},{"key":"B","text":"Upotrebiti element.textContent=korisnik.","why":"innerHTML parsira primljeni niz kao HTML; nepouzdan unos zato može postati markup sa aktivnim sadržajem. Kada cilj nije interpretacija HTML-a, textContent prikazuje doslovan tekst i ne stvara elemente niti event handlere iz sadržaja.","ok":true},{"key":"C","text":"Sakrivanje elementa uklanja XSS iz aplikacije.","why":"Ova pretpostavka ne važi: Sakrivanje elementa uklanja XSS iz aplikacije. innerHTML parsira primljeni niz kao HTML; nepouzdan unos zato može postati markup sa aktivnim sadržajem. Kada cilj nije interpretacija HTML-a, textContent prikazuje doslovan tekst i ne stvara elemente niti event handlere iz sadržaja.","ok":false}],"tacanOdgovor":"Upotrebiti element.textContent=korisnik.","objasnjenje":"innerHTML parsira primljeni niz kao HTML; nepouzdan unos zato može postati markup sa aktivnim sadržajem. Kada cilj nije interpretacija HTML-a, textContent prikazuje doslovan tekst i ne stvara elemente niti event handlere iz sadržaja. Za legitimno bogat HTML potrebna je stroga sanitizacija i odgovarajuća bezbednosna politika.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Browser nije granica poverenja; autentifikacija identifikuje klijenta, autorizacija proverava pravo konkretne komande.","ocekivaniRezultat":"Upotrebiti element.textContent=korisnik.","predlogPopravke":"element.textContent=korisnik;","pripremaTestOkruzenja":"const element=document.createElement("div"); document.body.append(element);","provera-popravke":"potrebna"},{"id":"10-r01","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Kome veruje server","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"const req={body:{uloga:"operater"},session:{uloga:"posmatrac"}};
console.log(req.body.uloga===req.session.uloga);","pitanje":"Šta se ispisuje i kojem podatku server sme da veruje?","opcije":[{"key":"A","text":"true; oba polja dolaze od korisnika","why":"Ne važi tvrdnja „true; oba polja dolaze od korisnika”. Korisnik može proizvoljno sastaviti JSON.","ok":false},{"key":"B","text":"false; veruje svojoj sesiji, ne proizvoljnom JSON polju.","why":"Tačan zaključak. Korisnik može proizvoljno sastaviti JSON. Serverska sesija je proverena na strani kojoj server veruje, zato se pravo na PUT određuje iz req.session.uloga. Samo postojanje polja uloga u telu ne povećava pravo.","ok":true},{"key":"C","text":"false; veruje body.uloga jer je zahtev ispravan JSON","why":"Ne važi tvrdnja „false; veruje body.uloga jer je zahtev ispravan JSON”. Korisnik može proizvoljno sastaviti JSON.","ok":false}],"tacanOdgovor":"false; veruje svojoj sesiji, ne proizvoljnom JSON polju.","objasnjenje":"Korisnik može proizvoljno sastaviti JSON. Serverska sesija je proverena na strani kojoj server veruje, zato se pravo na PUT određuje iz req.session.uloga. Samo postojanje polja uloga u telu ne povećava pravo.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"false; veruje svojoj sesiji, ne proizvoljnom JSON polju.","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"10-r02","vrsta":"predvidi","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-okruzenje-ili-mock","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"TextContent za nepouzdan unos","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"const el=document.createElement("div");
el.textContent="<b>24</b>";
console.log(el.querySelector("b")===null);","pitanje":"Koji je rezultat?","opcije":[{"key":"A","text":"true","why":"Tačan zaključak. textContent postavlja doslovan tekst, a ne parsira HTML. Zato ne nastaje b element; querySelector vraća null. Kod nepouzdanog unosa ovo izbegava aktiviranje HTML markup-a i event handlera kroz taj tekst.","ok":true},{"key":"B","text":"false","why":"Ne važi tvrdnja „false”. textContent postavlja doslovan tekst, a ne parsira HTML.","ok":false},{"key":"C","text":"TypeError","why":"Ne važi tvrdnja „TypeError”. textContent postavlja doslovan tekst, a ne parsira HTML.","ok":false}],"tacanOdgovor":"true","objasnjenje":"textContent postavlja doslovan tekst, a ne parsira HTML. Zato ne nastaje b element; querySelector vraća null. Kod nepouzdanog unosa ovo izbegava aktiviranje HTML markup-a i event handlera kroz taj tekst.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"true","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"10-r03","vrsta":"ispravi-gresku","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Pogrešno poverenje u sakriveno dugme","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"Frontend: button.hidden = true
Backend: svaki PUT /api/ventilator menja stanje, bez provere sesije","pitanje":"Šta je stvarni bezbednosni propust?","opcije":[{"key":"A","text":"Nedostaje CSS display:none","why":"Ne važi tvrdnja „Nedostaje CSS display:none”. Browser može sakriti kontrolu, ali korisnik i drugi HTTP klijenti mogu direktno poslati PUT.","ok":false},{"key":"B","text":"Potrebno je smanjiti veličinu button elementa","why":"Ne važi tvrdnja „Potrebno je smanjiti veličinu button elementa”. Browser može sakriti kontrolu, ali korisnik i drugi HTTP klijenti mogu direktno poslati PUT.","ok":false},{"key":"C","text":"Backend ne proverava pravo na komandu.","why":"Tačan zaključak. Browser može sakriti kontrolu, ali korisnik i drugi HTTP klijenti mogu direktno poslati PUT. Server mora proveriti autentifikaciju i autorizaciju pre mutacije. UI je samo korisnički interfejs, ne granica poverenja.","ok":true}],"tacanOdgovor":"Backend ne proverava pravo na komandu.","objasnjenje":"Browser može sakriti kontrolu, ali korisnik i drugi HTTP klijenti mogu direktno poslati PUT. Server mora proveriti autentifikaciju i autorizaciju pre mutacije. UI je samo korisnički interfejs, ne granica poverenja.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"Backend ne proverava pravo na komandu.","predlogPopravke":"U serverskom handler-u proveriti ulogu operatera i odbiti ostale zahteve statusom 401/403 prema situaciji.","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema","provera-popravke":"potrebna"}]}

{"predavanjeMinuta":55,"diskusijaMinuta":35,"samostalniZadaci":"van-casa","preduslov":"Cookie nosi ključ. Kutija drži ulogu.","rezervaNapomena":"Tip i predlog asistenta ostanu rečenica, bez novog glasanja.","samostalnoUcenje":{"uvod":"Ova tema razvija Kontrolnu sobu kroz poznat problem. Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz. Pre nego što otvoriš objašnjenje pitalice, napiši sopstvenu pretpostavku, pokreni kod i uporedi stvarni ishod sa očekivanjem.","detaljnoGradivo":["Celokupna aplikacija povezuje kontrolni UI, HTTP komunikaciju, Node server i PostgreSQL transakciju. Problem nije samo da li je dugme promenilo natpis, već koja komponenta trenutno poseduje potvrđenu informaciju. Ekran može prikazivati optimističku pretpostavku, poslednje očitavanje ili grešku; nijedno od toga nije automatski dokaz fizičkog efekta.","Kod timeout-a zahtev je možda stigao i izvršen, ali je odgovor izgubljen. Ponavljanje je bezbednije kada operacija postavlja željeno stanje i kada sistem ume da proveri ili deduplikuje pokušaje. Dijagnostika prati zahtev kroz Network panel, serverske logove i stanje baze. Zaključak mora da se zasniva na dokazu, ne na odsustvu poruke.","LLM može predložiti kod, refaktorisanje ili objašnjenje, ali njegovi zaključci nisu merodavni bez provere. Za svaki predlog formuliši testabilnu tvrdnju, pokreni minimalan primer, proveri granice ulaza i vrati se dokumentaciji ili izvornom kodu. TypeScript može otkriti neke greške pre izvršavanja, ali ne validira JSON tokom rada. Time se kurs završava metodom inženjerske provere, a ne učenjem još jednog frameworka.","Sada posmatraj ceo put jedne komande od klika, preko HTTP zahteva, validacije i autorizacije u Node-u do PostgreSQL transakcije i odgovora. Network panel govori šta je browser zaista primio, logovi šta je server video, a baza šta je potvrđeno. Razlika u tragovima nije greška analize, nego suština distribuiranog rada.","Najvažniji završni problem je nepoznat ishod. Server može potvrditi promenu u bazi i izgubiti odgovor na putu do klijenta. Timeout nije dokaz da operacija nije izvršena. Potrebni su bezbedno ponavljanje, provera stanja, ID komande i eventualno deduplikacija, u zavisnosti od zahteva sistema.","LLM koristi kao pomoć pri predlaganju hipoteza i pregledanju koda, a ne kao izvor istine. Ako tvrdi da fetch automatski baca grešku na 500, napravi minimalan kontraprimer. Ako predloži polling kod, proveri preklopljene zahteve i starije odgovore. TypeScript anotacija pomaže u statičkoj analizi, ali ne proverava proizvoljan JSON koji je stigao u toku rada."],"tokRada":"1) Pročitaj problem i opiši šta očekuješ. 2) Odgovori bez izvršavanja. 3) Otvori detaljno objašnjenje svih opcija. 4) Pokreni primer u izolovanom editoru. 5) Izmeni jedan detalj i ponovi eksperiment. 6) Vrati se Kontrolnoj sobi i poveži naučeno sa njenim fajlovima.","graniceZnanja":"Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz. Pretpostavke o serveru, browseru i bazi moraš navesti eksplicitno; kada zavise od konfiguracije, odgovor nije univerzalan.","proveraRazumevanja":"Na kraju teme navedi jednu pogrešnu pretpostavku koju si promenio, pokaži konkretan red koda ili HTTP zapis koji je razotkriva i objasni kako bi isti problem nastao u Kontrolnoj sobi."},"dodatniPrimeri":[{"id":"11-e01","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"Nepoznat ishod","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"PUT /api/ventilator -> server potvrdi u bazi
HTTP odgovor se izgubi pre browsera","pitanje":"Šta klijent može zaključiti samo iz timeout-a?","opcije":[{"key":"A","text":"Ne zna da li je upis uspeo; potreban je dodatni dokaz.","why":"Timeout opisuje iskustvo klijenta, a ne nužno konačno stanje servera. Zahtev je možda izvršen i potvrđen pre prekida odgovora, ili nikada nije stigao.","ok":true},{"key":"B","text":"Upis sigurno nije uspeo.","why":"Ova pretpostavka ne važi: Upis sigurno nije uspeo. Timeout opisuje iskustvo klijenta, a ne nužno konačno stanje servera. Zahtev je možda izvršen i potvrđen pre prekida odgovora, ili nikada nije stigao.","ok":false},{"key":"C","text":"Upis sigurno jeste uspeo.","why":"Ova pretpostavka ne važi: Upis sigurno jeste uspeo. Timeout opisuje iskustvo klijenta, a ne nužno konačno stanje servera. Zahtev je možda izvršen i potvrđen pre prekida odgovora, ili nikada nije stigao.","ok":false}],"tacanOdgovor":"Ne zna da li je upis uspeo; potreban je dodatni dokaz.","objasnjenje":"Timeout opisuje iskustvo klijenta, a ne nužno konačno stanje servera. Zahtev je možda izvršen i potvrđen pre prekida odgovora, ili nikada nije stigao. Zato slepo ponavljanje ne-idempotentne komande može biti opasno. Korisni mehanizmi su provera aktuelnog stanja, identifikator komande, deduplikacija i logovi uz dobro definisan API ugovor.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz.","ocekivaniRezultat":"Ne zna da li je upis uspeo; potreban je dodatni dokaz."},{"id":"11-e02","vrsta":"predvidi","jezik":"typescript","nivo":"Treca godina","izvrsavanje":"uz-typescript-okolinu","okruzenje":"typescript-kompilacija","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"TypeScript nije runtime validacija","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"type Soba={temperatura:number};
const telo: Soba=JSON.parse('{"temperatura":"toplo"}');
console.log(typeof telo.temperatura);","pitanje":"Šta se ispisuje tokom izvršavanja JavaScripta?","opcije":[{"key":"A","text":"number","why":"Ova pretpostavka ne važi: number. TypeScript anotacija postoji u fazi statičke provere i ne menja realnu vrednost koju JSON.parse vrati u JavaScript runtime-u. JSON.parse uspešno prihvata string "toplo" kao vrednost polja temperatura.","ok":false},{"key":"B","text":"TypeError pri parsiranju JSON-a","why":"Ova pretpostavka ne važi: TypeError pri parsiranju JSON-a. TypeScript anotacija postoji u fazi statičke provere i ne menja realnu vrednost koju JSON.parse vrati u JavaScript runtime-u. JSON.parse uspešno prihvata string "toplo" kao vrednost polja temperatura.","ok":false},{"key":"C","text":"string","why":"TypeScript anotacija postoji u fazi statičke provere i ne menja realnu vrednost koju JSON.parse vrati u JavaScript runtime-u. JSON.parse uspešno prihvata string "toplo" kao vrednost polja temperatura.","ok":true}],"tacanOdgovor":"string","objasnjenje":"TypeScript anotacija postoji u fazi statičke provere i ne menja realnu vrednost koju JSON.parse vrati u JavaScript runtime-u. JSON.parse uspešno prihvata string "toplo" kao vrednost polja temperatura. Da bi API granica bila pouzdana, server ili klijent mora proveriti stvarno pristigla polja i njihove tipove tokom izvršavanja. Type assertion ili anotacija nije zamena za validaciju.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz.","ocekivaniRezultat":"string"},{"id":"11-e03","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-mock-api","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"LLM pogrešno tumači fetch","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"// LLM predlog:
const r=await fetch("/api/soba");
// 500 će automatski otići u catch
show(await r.json());","pitanje":"Koja tvrdnja je pogrešna i kako je dokazati?","opcije":[{"key":"A","text":"catch automatski obrađuje 500 u svim browserima.","why":"Ova pretpostavka ne važi: catch automatski obrađuje 500 u svim browserima. Model je ponudio plauzibilnu, ali netačnu pretpostavku o API ponašanju. Proveri je minimalnim eksperimentom: na serveru vrati 500, posmatraj resolved Response i response.ok=false, pa eksplicitno pokreni granu greške.","ok":false},{"key":"B","text":"HTTP 500 sam ne odbacuje fetch Promise; proveriti r.ok i simulirati 500.","why":"Model je ponudio plauzibilnu, ali netačnu pretpostavku o API ponašanju. Proveri je minimalnim eksperimentom: na serveru vrati 500, posmatraj resolved Response i response.ok=false, pa eksplicitno pokreni granu greške.","ok":true},{"key":"C","text":"Sve što LLM napiše važi ako kod izgleda uredno.","why":"Ova pretpostavka ne važi: Sve što LLM napiše važi ako kod izgleda uredno. Model je ponudio plauzibilnu, ali netačnu pretpostavku o API ponašanju. Proveri je minimalnim eksperimentom: na serveru vrati 500, posmatraj resolved Response i response.ok=false, pa eksplicitno pokreni granu greške.","ok":false}],"tacanOdgovor":"HTTP 500 sam ne odbacuje fetch Promise; proveriti r.ok i simulirati 500.","objasnjenje":"Model je ponudio plauzibilnu, ali netačnu pretpostavku o API ponašanju. Proveri je minimalnim eksperimentom: na serveru vrati 500, posmatraj resolved Response i response.ok=false, pa eksplicitno pokreni granu greške. Dobar postupak sa LLM-om uključuje jasno definisan zahtev, verifikaciju uz standardnu dokumentaciju i proveru krajnjih slučajeva, umesto prihvatanja teksta po autoritetu.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz.","ocekivaniRezultat":"HTTP 500 sam ne odbacuje fetch Promise; proveriti r.ok i simulirati 500.","predlogPopravke":"const r=await fetch("/api/soba");if(!r.ok) throw new Error(`HTTP ${r.status}`);","pripremaTestOkruzenja":"const fetch=async()=>new Response(JSON.stringify({greska:"simulirano"}),{status:500,headers:{"Content-Type":"application/json"}}); const show=console.log;","provera-popravke":"potrebna"},{"id":"11-e04","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-mock-api","odgovorOdlozen":true,"uticajNaAplikaciju":"nema","editorPrimer":true,"naslov":"LLM skrivena trka","uvod":"Najpre predvidi rezultat bez pokretanja. Objasni jednu pretpostavku na kojoj tvoj odgovor počiva. Zatim pokreni primer ili ga proveri u odgovarajućem okruženju, pa uporedi sa objašnjenjem.","kod":"// LLM predlog:
setInterval(async()=>{const r=await fetch("/api/soba");show(await r.json())},1000);","pitanje":"Koji problem ostaje i kada svaki zahtev uspe?","opcije":[{"key":"A","text":"Odgovori mogu stići van redosleda i prepisati noviji prikaz.","why":"await suspenduje samo konkretni async callback, a interval i dalje može pokrenuti sledeći zahtev. Ako prethodni odgovor zakasni, njegov rezultat može prepisati noviji.","ok":true},{"key":"B","text":"Nema problema jer await suspenduje sve intervale.","why":"Ova pretpostavka ne važi: Nema problema jer await suspenduje sve intervale. await suspenduje samo konkretni async callback, a interval i dalje može pokrenuti sledeći zahtev. Ako prethodni odgovor zakasni, njegov rezultat može prepisati noviji.","ok":false},{"key":"C","text":"Uvek se prikazuje najnovije očitavanje.","why":"Ova pretpostavka ne važi: Uvek se prikazuje najnovije očitavanje. await suspenduje samo konkretni async callback, a interval i dalje može pokrenuti sledeći zahtev. Ako prethodni odgovor zakasni, njegov rezultat može prepisati noviji.","ok":false}],"tacanOdgovor":"Odgovori mogu stići van redosleda i prepisati noviji prikaz.","objasnjenje":"await suspenduje samo konkretni async callback, a interval i dalje može pokrenuti sledeći zahtev. Ako prethodni odgovor zakasni, njegov rezultat može prepisati noviji. LLM predlog zato nije dovršen dok ne definiše politiku preklapanja, verzionisanja očitavanja, otkazivanja zahteva ili samo jednog aktivnog čitanja. Student treba da pokaže scenario u kom greška nastaje i minimalnu korekciju.","promeniIProveri":"Promeni jedan uslov iz primera, napiši novo očekivanje i tek onda ponovi proveru. Kod sa browserom koristi DOM okruženje, a HTTP/SQL scenarije pokreći samo u odgovarajućem simuliranom servisu.","vezaSaAplikacijom":"Vidljivi UI nije dokaz potvrde transakcije. Nepoznat ishod, runtime validacija i LLM proveravanje zahtevaju konkretan eksperiment i dokaz.","ocekivaniRezultat":"Odgovori mogu stići van redosleda i prepisati noviji prikaz.","predlogPopravke":"Odbaci rezultat starijeg server-side timestamp-a ili koristi kontrolu jednog aktivnog zahteva.","provera-popravke":"potrebna"},{"id":"11-r01","vrsta":"predvidi","jezik":"text","nivo":"Treca godina","izvrsavanje":"konceptualno","okruzenje":"konceptualni-zapis","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"Timeout posle COMMIT-a","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"Server: BEGIN → UPDATE → INSERT → COMMIT
Mreža: odgovor se izgubi
Klijent: timeout","pitanje":"Koji je tačan zaključak iz ugla klijenta?","opcije":[{"key":"A","text":"Komanda sigurno nije izvršena","why":"Ne važi tvrdnja „Komanda sigurno nije izvršena”. Server je potvrdio bazu, ali klijent nije primio odgovor.","ok":false},{"key":"B","text":"Ishod je nepoznat bez dodatne provere.","why":"Tačan zaključak. Server je potvrdio bazu, ali klijent nije primio odgovor. Iz samog timeout-a ne može zaključiti da operacija nije uspela. Za pouzdano ponašanje treba proveriti server stanje, korelacijski ID i semantiku ponavljanja.","ok":true},{"key":"C","text":"Svakako treba ponoviti toggle","why":"Ne važi tvrdnja „Svakako treba ponoviti toggle”. Server je potvrdio bazu, ali klijent nije primio odgovor.","ok":false}],"tacanOdgovor":"Ishod je nepoznat bez dodatne provere.","objasnjenje":"Server je potvrdio bazu, ali klijent nije primio odgovor. Iz samog timeout-a ne može zaključiti da operacija nije uspela. Za pouzdano ponašanje treba proveriti server stanje, korelacijski ID i semantiku ponavljanja.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"Ishod je nepoznat bez dodatne provere.","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"11-r02","vrsta":"predvidi","jezik":"typescript","nivo":"Treca godina","izvrsavanje":"uz-typescript-okolinu","okruzenje":"typescript-kompilacija","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"TS anotacija ne čisti JSON","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"type Ocitavanje = { temperatura: number };
const telo = JSON.parse('{"temperatura":"24"}') as Ocitavanje;
console.log(typeof telo.temperatura);","pitanje":"Šta se ispisuje u izvršenom JavaScriptu?","opcije":[{"key":"A","text":"string","why":"Tačan zaključak. TypeScript assertion ne menja runtime vrednost. JSON.parse vraća string "24", pa typeof daje string. Ako aplikacija očekuje number, mora proveriti i eventualno konvertovati podatak uz validaciju, umesto da se oslanja na as tip.","ok":true},{"key":"B","text":"number","why":"Ne važi tvrdnja „number”. TypeScript assertion ne menja runtime vrednost.","ok":false},{"key":"C","text":"TypeError pri JSON.parse","why":"Ne važi tvrdnja „TypeError pri JSON.parse”. TypeScript assertion ne menja runtime vrednost.","ok":false}],"tacanOdgovor":"string","objasnjenje":"TypeScript assertion ne menja runtime vrednost. JSON.parse vraća string "24", pa typeof daje string. Ako aplikacija očekuje number, mora proveriti i eventualno konvertovati podatak uz validaciju, umesto da se oslanja na as tip.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"string","odgovor_odlozen":"da","uticaj_na_aplikaciju":"nema"},{"id":"11-r03","vrsta":"ispravi-gresku","jezik":"javascript","nivo":"Treca godina","izvrsavanje":"uz-pripremljeno-okruzenje","okruzenje":"zahteva-mock-api","odgovorOdlozen":false,"uticajNaAplikaciju":null,"editorPrimer":true,"naslov":"LLM bez proverljivog dokaza","uvod":"Predvidi odgovor ili pronađi grešku pre izvršavanja. Zapiši pretpostavku, pa proveri tek nakon izbora; rad je nezavisan od fajlova Kontrolne sobe.","kod":"// LLM: "Ovaj kod proverava uspeh HTTP zahteva"
async function procitaj() {
 const odgovor = await fetch("/api/soba");
 return await odgovor.json();
}
procitaj().then(console.log);","pitanje":"Šta treba proveriti pre tumačenja JSON-a kao uspešnog očitavanja?","opcije":[{"key":"A","text":"Dovoljno je postojanje telo.temperatura","why":"Ne važi tvrdnja „Dovoljno je postojanje telo.temperatura”. fetch se može uspešno razrešiti HTTP odgovorom sa statusom 404 ili 500, a JSON može imati neodgovarajuću strukturu.","ok":false},{"key":"B","text":"Promise rešen znači da je i server uspešno izvršio radnju","why":"Ne važi tvrdnja „Promise rešen znači da je i server uspešno izvršio radnju”. fetch se može uspešno razrešiti HTTP odgovorom sa statusom 404 ili 500, a JSON može imati neodgovarajuću strukturu.","ok":false},{"key":"C","text":"response.ok, zatim oblik i tip parsiranih podataka.","why":"Tačan zaključak. fetch se može uspešno razrešiti HTTP odgovorom sa statusom 404 ili 500, a JSON može imati neodgovarajuću strukturu. Uslov response.ok i runtime validacija rešavaju odvojene probleme. LLM je dao moguć kod, ali nije dokazao svoj komentar.","ok":true}],"tacanOdgovor":"response.ok, zatim oblik i tip parsiranih podataka.","objasnjenje":"fetch se može uspešno razrešiti HTTP odgovorom sa statusom 404 ili 500, a JSON može imati neodgovarajuću strukturu. Uslov response.ok i runtime validacija rešavaju odvojene probleme. LLM je dao moguć kod, ali nije dokazao svoj komentar.","promeniIProveri":"Promeni jedan ulaz ili pravilo, predvidi novi rezultat i pokreni u naznačenom okruženju. Kod primera sa kvarom prvo pokušaj samostalnu popravku.","vezaSaAplikacijom":"Prenesi isti mehanizam na Kontrolnu sobu: šta bi se promenilo u prikazu, HTTP zahtevu, serverskom stanju ili bazi?","ocekivaniRezultat":"response.ok, zatim oblik i tip parsiranih podataka.","predlogPopravke":"async function procitaj() {
 const odgovor = await fetch("/api/soba");
 if (!odgovor.ok) throw new Error(`HTTP ${odgovor.status}`);
